<template>
  <view class="dz-page order-list-page">
    <header class="page-head"><button aria-label="返回" @tap="goBack">‹</button><text>我的订单</text></header>
    <scroll-view scroll-x class="tabs" :show-scrollbar="false"><view class="tab-row"><button v-for="tab in orderTabs" :key="tab.key" :class="{active:activeTab===tab.key}" @tap="activeTab=tab.key">{{ tab.label }}</button></view></scroll-view>
    <main class="list-content">
      <view v-if="loading" class="state">正在加载订单…</view>
      <view v-else-if="error" class="state"><text>{{ error }}</text><button @tap="loadOrders">重新加载</button></view>
      <view v-else-if="!visibleOrders.length" class="state"><i>▤</i><strong>暂无相关订单</strong><text>预约达人服务后，订单会显示在这里。</text><button @tap="browseProviders">去找达人</button></view>
      <section v-for="order in visibleOrders" :key="order.order_no" class="order-card" @tap="openOrder(order.order_no)">
        <view class="card-head"><text>达人服务</text><strong>{{ orderStatusCopy(order.status).title }}</strong></view>
        <view class="provider-row"><view class="avatar"><image v-if="order.provider_avatar_url" :src="order.provider_avatar_url" mode="aspectFill"/><text v-else>{{ order.provider_name.slice(0,1) }}</text></view><view class="provider-copy"><strong>{{ order.provider_name }} · {{ order.service_name }}</strong><text>◷ {{ formatRange(order.starts_at,order.ends_at) }}</text><text>● {{ order.meeting_address }}</text></view><view class="amount"><text>合计</text><strong>¥{{ money(order.payable_amount) }}</strong></view></view>
        <view class="card-foot"><text>订单号 {{ order.order_no }}</text><view><button v-if="order.status==='pending_payment'" class="outline" @tap.stop="cancel(order)">取消订单</button><button v-if="order.status==='pending_payment'" class="primary" @tap.stop="continuePay(order)">继续支付</button><button v-else class="outline" @tap.stop="openOrder(order.order_no)">查看详情</button></view></view>
      </section>
    </main>
  </view>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'; import { onLoad, onShow } from '@dcloudio/uni-app'; import { cancelProviderOrder, getProviderOrders } from '@/services/orders'; import { inOrderBucket, orderStatusCopy, orderTabs } from '@/services/orderPresentation'; import type { OrderBucket } from '@/services/orderPresentation'; import type { ProviderOrder } from '@/types/api'; import { formatAmount, getErrorMessage } from '@/utils/formatters'
const orders=ref<ProviderOrder[]>([]),activeTab=ref<OrderBucket>('all'),loading=ref(true),error=ref(''),hasLoaded=ref(false);const visibleOrders=computed(()=>orders.value.filter(item=>inOrderBucket(item.status,activeTab.value)));const money=formatAmount
function formatRange(start:string,end:string){const s=new Date(start),e=new Date(end);return `${String(s.getMonth()+1).padStart(2,'0')}月${String(s.getDate()).padStart(2,'0')}日 ${String(s.getHours()).padStart(2,'0')}:${String(s.getMinutes()).padStart(2,'0')}—${String(e.getHours()).padStart(2,'0')}:${String(e.getMinutes()).padStart(2,'0')}`}
function goBack(){uni.navigateBack()}function browseProviders(){uni.reLaunch({url:'/pages/providers/list'})}function openOrder(orderNo:string){uni.navigateTo({url:`/pages/orders/detail?orderNo=${orderNo}`})}function continuePay(order:ProviderOrder){uni.navigateTo({url:`/pages/booking/payment?orderNo=${order.order_no}`})}
function cancel(order:ProviderOrder){uni.showModal({title:'取消订单',content:'订单尚未支付，取消后将立即释放达人档期。',success:async result=>{if(!result.confirm)return;try{await cancelProviderOrder(order.order_no);await loadOrders()}catch(reason){uni.showToast({title:getErrorMessage(reason,'取消失败'),icon:'none'})}}})}
async function loadOrders(){loading.value=true;error.value='';try{orders.value=(await getProviderOrders()).data.items;hasLoaded.value=true}catch(reason){error.value=getErrorMessage(reason)}finally{loading.value=false}}
onLoad(query=>{const value=typeof query?.status==='string'?query.status:'all';if(orderTabs.some(item=>item.key===value))activeTab.value=value as OrderBucket});onShow(()=>{if(hasLoaded.value)loadOrders();else loadOrders()})
</script>

<style lang="scss" scoped>
@use '../../styles/tokens.scss' as *;
.order-list-page{min-height:100vh;background:$dz-surface-page}.page-head{position:sticky;z-index:10;top:0;display:flex;align-items:flex-end;justify-content:center;height:calc(98rpx + env(safe-area-inset-top));padding-bottom:18rpx;background:#fff;box-sizing:border-box}.page-head button{position:absolute;left:20rpx;bottom:7rpx;width:70rpx;height:70rpx;margin:0;padding:0;border:0;background:transparent;font-size:50rpx;line-height:70rpx}.page-head button::after,.tabs button::after,.card-foot button::after,.state button::after{display:none}.page-head text{font-size:31rpx;font-weight:700}.tabs{position:sticky;z-index:9;top:calc(98rpx + env(safe-area-inset-top));height:82rpx;background:#fff;white-space:nowrap}.tab-row{display:flex;min-width:100%;height:82rpx}.tab-row button{position:relative;flex:1;min-width:130rpx;height:82rpx;margin:0;padding:0;border:0;background:#fff;color:$dz-text-secondary;font-size:22rpx;line-height:82rpx}.tab-row button.active{color:$dz-text-primary;font-weight:700}.tab-row button.active::before{position:absolute;bottom:4rpx;left:50%;width:40rpx;height:6rpx;border-radius:3rpx;background:$dz-brand-primary;content:'';transform:translateX(-50%)}.list-content{padding:20rpx 22rpx 50rpx}.order-card{margin-bottom:18rpx;padding:0 20rpx;border-radius:22rpx;background:#fff;box-shadow:$dz-shadow-card}.card-head{display:flex;align-items:center;justify-content:space-between;height:72rpx;border-bottom:1rpx solid $dz-border-subtle;font-size:21rpx}.card-head text{font-weight:700}.card-head strong{color:$dz-brand-deep}.provider-row{display:flex;align-items:flex-start;padding:22rpx 0}.avatar{display:flex;align-items:center;justify-content:center;overflow:hidden;width:92rpx;height:92rpx;border-radius:18rpx;color:$dz-brand-deep;background:$dz-brand-soft;font-size:32rpx}.avatar image{width:100%;height:100%}.provider-copy{display:flex;flex:1;flex-direction:column;gap:9rpx;margin-left:16rpx;min-width:0}.provider-copy strong{font-size:23rpx}.provider-copy text{overflow:hidden;color:$dz-text-secondary;font-size:18rpx;text-overflow:ellipsis;white-space:nowrap}.amount{display:flex;flex-direction:column;align-items:flex-end;gap:8rpx;margin-left:10rpx;color:$dz-text-secondary;font-size:17rpx}.amount strong{color:$dz-price-primary;font-size:29rpx}.card-foot{display:flex;align-items:center;justify-content:space-between;min-height:84rpx;border-top:1rpx solid $dz-border-subtle}.card-foot>text{color:$dz-text-tertiary;font-size:16rpx}.card-foot>view{display:flex;gap:10rpx}.card-foot button{height:54rpx;margin:0;padding:0 20rpx;border-radius:27rpx;font-size:19rpx;line-height:54rpx}.card-foot .outline{border:1rpx solid $dz-border-subtle;color:$dz-text-primary;background:#fff}.card-foot .primary{border:0;color:#fff;background:$dz-gradient-brand}.state{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:580rpx;color:$dz-text-secondary;text-align:center;font-size:21rpx}.state i{color:$dz-brand-primary;font-size:78rpx;font-style:normal}.state strong{margin-top:20rpx;color:$dz-text-primary;font-size:28rpx}.state text{margin-top:12rpx}.state button{height:66rpx;margin:28rpx 0 0;padding:0 36rpx;border:0;border-radius:33rpx;color:#fff;background:$dz-gradient-brand;font-size:22rpx;line-height:66rpx}
</style>
